import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import 'package:intl/intl.dart';

const pink = Color(0xFFE83E8C);
const pale = Color(0xFFFFF2F8);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Add your Firebase options using FlutterFire CLI before running the app.
  await Firebase.initializeApp();
  runApp(const HayaApp());
}

class HayaApp extends StatelessWidget {
  const HayaApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'HAYA', debugShowCheckedModeBanner: false,
    theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: pink, primary: pink, surface: Colors.white), scaffoldBackgroundColor: pale, useMaterial3: true, textTheme: GoogleFonts.poppinsTextTheme(), appBarTheme: const AppBarTheme(backgroundColor: Colors.white, foregroundColor: pink, centerTitle: false)),
    home: const AuthGate());
}

class AuthGate extends StatelessWidget {
  const AuthGate({super.key});
  @override
  Widget build(BuildContext context) => StreamBuilder<User?>(
    stream: FirebaseAuth.instance.authStateChanges(),
    builder: (context, snap) { if (snap.connectionState == ConnectionState.waiting) return const Scaffold(body: Center(child: CircularProgressIndicator())); return snap.data == null ? const LoginPage() : const HomePage(); });
}

class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage> {
 final email=TextEditingController(), password=TextEditingController(), name=TextEditingController(); bool signup=false, busy=false; String error='';
 Future<void> submit() async { setState((){busy=true;error='';}); try { if(signup){ final c=await FirebaseAuth.instance.createUserWithEmailAndPassword(email:email.text.trim(),password:password.text); await c.user!.updateDisplayName(name.text.trim().isEmpty?'HAYA User':name.text.trim()); await FirebaseFirestore.instance.collection('users').doc(c.user!.uid).set({'name':name.text.trim().isEmpty?'HAYA User':name.text.trim(),'email':email.text.trim(),'coins':100,'role':'user','createdAt':FieldValue.serverTimestamp()}); } else { await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text); } } on FirebaseAuthException catch(e){setState(()=>error=e.message??'Sign in failed');} catch(e){setState(()=>error='Setup error: Firebase config missing or network unavailable.');} finally{if(mounted)setState(()=>busy=false);} }
 @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Card(color:Colors.white,elevation:3,child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.favorite, color:pink,size:56),Text('HAYA',textAlign:TextAlign.center,style:GoogleFonts.poppins(fontSize:34,fontWeight:FontWeight.w800,color:pink)),const Text('Live Chat • Gaming • Friends',textAlign:TextAlign.center),const SizedBox(height:24),if(signup) TextField(controller:name,decoration:const InputDecoration(labelText:'Display name',prefixIcon:Icon(Icons.person))),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',prefixIcon:Icon(Icons.email))),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password (6+ characters)',prefixIcon:Icon(Icons.lock))),if(error.isNotEmpty) Padding(padding:const EdgeInsets.only(top:8),child:Text(error,style:const TextStyle(color:Colors.red))),const SizedBox(height:16),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Please wait…':signup?'Create account':'Login')),TextButton(onPressed:()=>setState(()=>signup=!signup),child:Text(signup?'Already have an account? Login':'New here? Create an account'))]))))));
}

class HomePage extends StatefulWidget { const HomePage({super.key}); @override State<HomePage> createState()=>_HomePageState(); }
class _HomePageState extends State<HomePage> { int index=0; final pages=const [ChatPage(), GamesPage(), RoomsPage(), WalletPage(), ProfilePage()]; @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Row(children:[const Icon(Icons.favorite),const SizedBox(width:8),Text('HAYA',style:GoogleFonts.poppins(fontWeight:FontWeight.w800))]),actions:[IconButton(tooltip:'Admin panel',icon:const Icon(Icons.admin_panel_settings),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AdminPage())))]),body:pages[index],bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const [NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'Chat'),NavigationDestination(icon:Icon(Icons.sports_esports),label:'Games'),NavigationDestination(icon:Icon(Icons.mic_none),label:'Rooms'),NavigationDestination(icon:Icon(Icons.card_giftcard),label:'Gifts'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile') ])); }

class ChatPage extends StatefulWidget { const ChatPage({super.key}); @override State<ChatPage> createState()=>_ChatPageState(); }
class _ChatPageState extends State<ChatPage>{final text=TextEditingController(); final uid=FirebaseAuth.instance.currentUser!.uid; Future<void> send()async{final v=text.text.trim();if(v.isEmpty)return;text.clear();await FirebaseFirestore.instance.collection('messages').add({'text':v,'uid':uid,'name':FirebaseAuth.instance.currentUser!.displayName??'HAYA User','createdAt':FieldValue.serverTimestamp()});}
 @override Widget build(BuildContext context)=>Column(children:[Container(width:double.infinity,padding:const EdgeInsets.all(14),color:Colors.white,child:const Text('💗 Community Chat  ·  Be kind and respectful')),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('messages').orderBy('createdAt',descending:true).limit(100).snapshots(),builder:(context,s)=>s.hasError?const Center(child:Text('Chat setup required. Check Firebase and Firestore rules.')):!s.hasData?const Center(child:CircularProgressIndicator()):ListView(reverse:true,padding:const EdgeInsets.all(12),children:s.data!.docs.map((d){final m=d.data();final mine=m['uid']==uid;final ts=m['createdAt'];return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.symmetric(vertical:5),padding:const EdgeInsets.all(12),constraints:const BoxConstraints(maxWidth:300),decoration:BoxDecoration(color:mine?const Color(0xFFFFD7E8):Colors.white,borderRadius:BorderRadius.circular(16)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(m['name']??'User',style:const TextStyle(fontSize:11,fontWeight:FontWeight.bold,color:pink)),Text(m['text']??''),if(ts is Timestamp)Text(DateFormat('HH:mm').format(ts.toDate()),style:const TextStyle(fontSize:10,color:Colors.grey))])));}).toList()))),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:text,onSubmitted:(_)=>send(),decoration:InputDecoration(hintText:'Say something nice…',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(28),borderSide:BorderSide.none)))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send))])))]);}

class GamesPage extends StatefulWidget {const GamesPage({super.key});@override State<GamesPage> createState()=>_GamesPageState();}
class _GamesPageState extends State<GamesPage>{String result='Turn: X';List<String> cells=List.filled(9,'');String turn='X';void play(int i){if(cells[i].isNotEmpty||result.startsWith('Winner')||result=='Draw!')return;setState((){cells[i]=turn;final lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];if(lines.any((l)=>cells[l[0]].isNotEmpty&&cells[l[0]]==cells[l[1]]&&cells[l[1]]==cells[l[2]])){result='Winner: $turn 🎉';}else if(cells.every((c)=>c.isNotEmpty)){result='Draw!';}else{turn=turn=='X'?'O':'X';result='Turn: $turn';}});}void reset()=>setState((){cells=List.filled(9,'');turn='X';result='Turn: X';});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(18),children:[Text('Mini Games',style:Theme.of(context).textTheme.headlineSmall?.copyWith(color:pink,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Quick fun while you chat.'),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('Tic-Tac-Toe',style:TextStyle(fontWeight:FontWeight.bold,fontSize:20)),Text(result),const SizedBox(height:10),GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:9,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3),itemBuilder:(c,i)=>Padding(padding:const EdgeInsets.all(4),child:OutlinedButton(onPressed:()=>play(i),child:Text(cells[i],style:const TextStyle(fontSize:28,color:pink))))),TextButton(onPressed:reset,child:const Text('New game'))]))),const Card(child:ListTile(leading:Icon(Icons.extension,color:pink),title:Text('More games coming soon'),subtitle:Text('Online multiplayer requires a game server / matchmaking backend.')))]);}

class RoomsPage extends StatelessWidget {const RoomsPage({super.key});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Live Voice Rooms',style:Theme.of(context).textTheme.headlineSmall?.copyWith(color:pink,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Room directory preview. Connect a voice provider to enable real-time audio.'),for(final item in ['Friends Lounge','Music & Chill','Gaming Squad'])Card(child:ListTile(leading:const CircleAvatar(backgroundColor:pale,child:Icon(Icons.mic,color:pink)),title:Text(item),subtitle:const Text('Voice room • Demo'),trailing:FilledButton(onPressed:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text(item),content:const Text('Voice is not connected yet. Configure Agora or another WebRTC provider and add valid credentials to enable live audio.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('OK'))])),child:const Text('Join')))]);}

class WalletPage extends StatelessWidget {const WalletPage({super.key});@override Widget build(BuildContext context)=>StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').doc(FirebaseAuth.instance.currentUser!.uid).snapshots(),builder:(context,s){final coins=(s.data?.data()?['coins'] as num?)?.toInt()??0;return ListView(padding:const EdgeInsets.all(18),children:[Text('Coins & Gifts',style:Theme.of(context).textTheme.headlineSmall?.copyWith(color:pink,fontWeight:FontWeight.bold)),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[const Icon(Icons.account_balance_wallet,color:pink,size:46),const Text('Your demo balance',style:TextStyle(color:Colors.grey)),Text('$coins coins',style:const TextStyle(fontSize:30,fontWeight:FontWeight.bold,color:pink)),const Text('New accounts receive 100 demo coins. These have no cash value.')]))),const SizedBox(height:12),for(final gift in [('🌹','Rose',10),('💖','Heart',20),('👑','Crown',100)])Card(child:ListTile(leading:Text(gift.$1,style:const TextStyle(fontSize:30)),title:Text(gift.$2),subtitle:Text('${gift.$3} coins'),trailing:FilledButton(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Gift sending is demo-only until a trusted backend transaction is deployed.'))),child:const Text('Send')))]);});}

class ProfilePage extends StatelessWidget {const ProfilePage({super.key});@override Widget build(BuildContext context){final u=FirebaseAuth.instance.currentUser!;return ListView(padding:const EdgeInsets.all(20),children:[const CircleAvatar(radius:42,backgroundColor:pale,child:Icon(Icons.person,color:pink,size:48)),const SizedBox(height:12),Text(u.displayName??'HAYA User',textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineSmall),Text(u.email??'',textAlign:TextAlign.center),const SizedBox(height:20),const Card(child:ListTile(leading:Icon(Icons.verified_user,color:pink),title:Text('Account'),subtitle:Text('Signed in securely with Firebase Authentication'))),FilledButton.icon(onPressed:()=>FirebaseAuth.instance.signOut(),icon:const Icon(Icons.logout),label:const Text('Log out'))]);}}

class AdminPage extends StatelessWidget {const AdminPage({super.key});Future<bool> isAdmin()async{final token=await FirebaseAuth.instance.currentUser!.getIdTokenResult(true);return token.claims?['admin']==true;}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('HAYA Admin Panel')),body:FutureBuilder<bool>(future:isAdmin(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(!s.data!)return const Center(child:Padding(padding:EdgeInsets.all(24),child:Text('Admin access only. Set the Firebase custom claim admin=true using the Admin SDK from a trusted server. Never grant admin from the client app.')));return StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').snapshots(),builder:(context,u)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Registered users: ${u.data?.docs.length??0}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('User moderation and coin management should be implemented through trusted Cloud Functions before production.') ]));}));}
